//! Server-authored sound events, preserving registry/custom identities and positions.
use azalea_core::{position::Vec3,sound::CustomSound};
use azalea_registry::{builtin::SoundEvent,Holder};
#[derive(Debug,Clone,serde::Serialize)]
pub struct ServerSound{pub kind:String,pub name:String,pub position:[f64;3],pub volume:f32,pub pitch:f32,pub fixed_range:Option<f32>,pub seed:u64,pub seed_text:String,pub source:u8}
fn identity(sound:&Holder<SoundEvent,CustomSound>)->(String,Option<f32>){match sound{Holder::Reference(id)=>(id.to_string(),None),Holder::Direct(s)=>(s.sound_id.to_string(),s.range)}}
fn event(name:String,fixed_range:Option<f32>,p:Vec3,volume:f32,pitch:f32,seed:u64,source:u8)->Option<ServerSound>{
 let position=[p.x,p.y,p.z];if name.len()>256||name.is_empty()||!position.iter().all(|v|v.is_finite()&&v.abs()<=30_000_000.)||!volume.is_finite()||volume<0.||!pitch.is_finite()||pitch<=0.||fixed_range.is_some_and(|r|!r.is_finite()||r<0.){return None;}
 Some(ServerSound{kind:"play".into(),name:if name.contains(':'){name}else{format!("minecraft:{name}")},position,volume,pitch,fixed_range,seed,seed_text:seed.to_string(),source})
}
pub fn positional(p:&azalea_protocol::packets::game::ClientboundSound)->Option<ServerSound>{let(n,r)=identity(&p.sound);event(n,r,Vec3::new(p.x as f64/8.,p.y as f64/8.,p.z as f64/8.),p.volume,p.pitch,p.seed,p.source as u8)}
pub fn entity(p:&azalea_protocol::packets::game::ClientboundSoundEntity,world:&bevy_ecs::world::World,local:bevy_ecs::entity::Entity)->Option<ServerSound>{
 let target=world.get::<azalea_entity::indexing::EntityIdIndex>(local)?.get_by_minecraft_entity(p.id)?;
 if target!=local&&!world.get::<azalea_entity::LoadedBy>(target)?.0.contains(&local){return None;}
 let pos=world.get::<azalea_entity::Position>(target)?;let(n,r)=identity(&p.sound);event(n,r,Vec3::new(pos.x,pos.y,pos.z),p.volume,p.pitch,p.seed,p.source as u8)
}
pub fn explosion(p:&azalea_protocol::packets::game::ClientboundExplode)->Option<ServerSound>{let(name,range)=identity(&p.explosion_sound);event(name,range,p.center,4.,0.7,0,4)}
pub fn stop(p:&azalea_protocol::packets::game::ClientboundStopSound)->ServerSound{ServerSound{kind:"stop".into(),name:p.name.as_ref().map(ToString::to_string).unwrap_or_default(),position:[0.;3],volume:0.,pitch:1.,fixed_range:None,seed:0,seed_text:"0".into(),source:p.source.map(|s|s as u8).unwrap_or(255)}}
#[cfg(test)]mod tests{use super::*;use azalea_protocol::packets::game::{ClientboundSound,c_sound::SoundSource};
 #[test]fn eighth_block_positions_custom_range_seed_and_gain_preserved(){let p=ClientboundSound{sound:Holder::Direct(CustomSound{sound_id:"example:boss.hit".into(),range:Some(48.)}),source:SoundSource::Hostile,x:-81,y:512,z:19,volume:3.5,pitch:1.25,seed:9182};let s=positional(&p).unwrap();assert_eq!(s.name,"example:boss.hit");assert_eq!(s.position,[-10.125,64.,2.375]);assert_eq!(s.fixed_range,Some(48.));assert_eq!(s.volume,3.5);assert_eq!(s.pitch,1.25);assert_eq!(s.seed,9182);assert_eq!(s.source,5);}
 #[test]fn invalid_gain_and_position_do_not_play(){assert!(event("minecraft:test".into(),None,Vec3::new(f64::NAN,0.,0.),1.,1.,0,0).is_none());assert!(event("minecraft:test".into(),None,Vec3::ZERO,-1.,1.,0,0).is_none());assert!(event("minecraft:test".into(),Some(f32::INFINITY),Vec3::ZERO,1.,1.,0,0).is_none());}
 #[test]fn entity_sounds_require_current_session_loaded_actor(){use azalea_entity::{Position,LoadedBy,indexing::EntityIdIndex};use azalea_protocol::packets::game::ClientboundSoundEntity;let mut world=bevy_ecs::world::World::new();let local=world.spawn_empty().id();let target=world.spawn((Position::new(Vec3::new(4.,65.,8.)),LoadedBy(Default::default()))).id();let mut index=EntityIdIndex::default();index.insert(azalea_world::MinecraftEntityId(42),target);world.entity_mut(local).insert(index);let packet=ClientboundSoundEntity{sound:Holder::Reference(SoundEvent::ItemSpearHit),source:SoundSource::Players,id:azalea_world::MinecraftEntityId(42),volume:1.,pitch:1.,seed:7};assert!(entity(&packet,&world,local).is_none());world.get_mut::<LoadedBy>(target).unwrap().0.insert(local);assert_eq!(entity(&packet,&world,local).unwrap().position,[4.,65.,8.]);world.entity_mut(target).remove::<Position>();assert!(entity(&packet,&world,local).is_none());}
 #[test]fn stop_sound_retains_all_four_filter_forms(){use azalea_protocol::packets::game::ClientboundStopSound;for(source,name)in [(None,None),(Some(SoundSource::Players),None),(None,Some("minecraft:item.mace.smash_ground".into())),(Some(SoundSource::Hostile),Some("example:boss".into()))]{let expected_source=source.map(|s|s as u8).unwrap_or(255);let expected_name=name.as_ref().map(ToString::to_string).unwrap_or_default();let packet=ClientboundStopSound{source,name};let s=stop(&packet);assert_eq!(s.kind,"stop");assert_eq!(s.source,expected_source);assert_eq!(s.name,expected_name);assert_eq!(s.volume,0.);}}
 #[test]fn explosion_uses_actual_named_sound(){use azalea_entity::particle::Particle;let p=azalea_protocol::packets::game::ClientboundExplode{center:Vec3::new(1.,2.,3.),radius:3.,block_count:0,player_knockback:None,explosion_particle:Particle::Gust,explosion_sound:Holder::Reference(SoundEvent::EntityWindChargeWindBurst),block_particles:vec![]};let s=explosion(&p).unwrap();assert_eq!(s.name,"minecraft:entity.wind_charge.wind_burst");assert_eq!(s.position,[1.,2.,3.]);}
}
